        self.log = log
        self.policy = policy

    def _sha(self, b: bytes) -> str:
        return hashlib.sha256(b).hexdigest()

    def _serialize(self, value):
        # deterministic, stable across calls
        return value.detach().contiguous().cpu().numpy().astype('float32').tobytes()

    def _make_record(self, name, value):
        return {
            'name': name,
            'shape': tuple(value.shape),
