            raw = self._serialize(value)
            baseline[name] = {
                'name': name,
                'shape': tuple(value.shape),
                'dtype': str(value.dtype),
                'hash': self._sha(raw),
                'backup': raw if len(raw) <= MAX_BACKUP_BYTES else None,
