def _sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def _sha256_list(values):
    h = hashlib.sha256()
    h.update(b"")
    for i, v in enumerate(values):
        h.update(f"{i}:{type(v).__name__}:{repr(v)[:256]}").encode())
    return h.hexdigest()

def _to_float_list(t):
    try:
        return [float(x) for x in t.flatten().tolist()]
    except Exception:
        return []

def _sample_checksum(tensor, n=1024):
    flat = _to_float_list(tensor)
    if not flat:
        return None
    if len(flat) > n:
        # deterministic sample: first n and last n? Use first n only? For reproducibility use stride.
        step = max(1, len(flat)//n)
        sampled = flat[::step][:n]
    else:
        sampled = flat
    h = hashlib.sha256()
    for x in sampled:
        h.update(f"{x:.17g}\n").encode()
    return h.hexdigest(), float(sum(sampled)/len(sampled)), float(max(sampled)), float(min(sampled)), len(sampled)

